    /**
     * 获取智能事件相似案例
     *
     * @param context      context
     * @param csn          流水号
     * @param solutionName 解决方案名称
     * @return 响应结果
     */
    public ResponseResult retrieveAIIncidentCases(HttpContext context, Long csn, String solutionName) {
        if (StringUtils.isEmpty(solutionName)) {
            LOGGER.error("[retrieveAIIncidentCases] solutionName is empty for csn {}", csn);
            return ResponseResultHelper.failResponseEntity("missing solution name");
        }
        AIIncidentDetailParam aiIncidentDetailParam = new AIIncidentDetailParam();
        aiIncidentDetailParam.setIncidentCsn(csn);
        aiIncidentDetailParam.setSolutionName(solutionName);
        try {
            String incidentDetailParam = JSON.toJSONString(aiIncidentDetailParam);
            RestfulParametes incidentDetailRestfulParametes = new RestfulParametes();
            incidentDetailRestfulParametes.setRawData(incidentDetailParam);
            RestfulResponse incidentDetailResponse = RestUtil.sendRestRequest(context.getHttpServletRequest(), RestConstant.RESTFUL_METHOD_POST, AIINCIDENT_DETAIL_URL, incidentDetailRestfulParametes, null);
            if (incidentDetailResponse == null || incidentDetailResponse.getStatus() != RestConstant.STATUS_OK) {
                LOGGER.error("[retrieveAIIncidentCases] query incident detail error with csn {}", csn);
                return ResponseResultHelper.failResponseEntity("query incident detail failed");
            }
            ResponseResult incidentDetailResponseResult = JSON.parseObject(incidentDetailResponse.getResponseContent(), ResponseResult.class);
            String incidentDetailJsonData = JSON.toJSONString(incidentDetailResponseResult.getData());
            AIIncidentDetailResponse aiIncidentDetailResponse = JSON.parseObject(incidentDetailJsonData, AIIncidentDetailResponse.class);
            if (aiIncidentDetailResponse == null) {
                LOGGER.error("[retrieveAIIncidentCases] get incident detail null with csn {}", csn);
                return ResponseResultHelper.failResponseEntity("query incident detail failed");
            }
            List<KeyEvent> keyEventList = aiIncidentDetailResponse.getKeyEventList();
            if (CollectionUtils.isEmpty(keyEventList)) {
                LOGGER.error("[retrieveAIIncidentCases] empty incident key event list with csn {}", csn);
                return ResponseResultHelper.failResponseEntity("incident detail error");
            }
            KeyEvent keyEvent = keyEventList.getFirst();
            if (keyEvent == null) {
                LOGGER.error("[retrieveAIIncidentCases] empty incident key event with csn {}", csn);
                return ResponseResultHelper.failResponseEntity("incident detail error");
            }
            String query = keyEvent.getName();
            if (StringUtils.isEmpty(query)) {
                LOGGER.error("[retrieveAIIncidentCases] empty key event name with csn {}", csn);
                return ResponseResultHelper.failResponseEntity("incident detail error");
            }
            return ResponseResultHelper.correctResponseEntity(queryAILlmEngineIncidentCases(context, keyEvent.getAlarmId(), query, csn));
        } catch (ServiceException e) {
            LOGGER.error("[retrieveAIIncidentCases] ServiceException while getting incident cases for csn {}: {}", csn, e.getMessage(), e);
            return ResponseResultHelper.failResponseEntity("ServiceException while getting incident cases for csn " + csn);
        } catch (Exception e) {
            LOGGER.error("Unexpected error while getting incident cases for csn {}: {}", csn, e.getMessage(), e);
            return ResponseResultHelper.failResponseEntity("Unexpected error while getting incident cases");
        }
    }

    /**
