    private String extractAlarmId(String knowledgeTitle) {
        Matcher matcher = ALARM_PATTERN.matcher(knowledgeTitle);
        if (matcher.find()) {
            return matcher.group(1);
        } else {
            return "";
        }
    }

    /**
     * LLM Engine智能事件案例检索
     *
     * @param context   context
     * @param alarmId   alarmId
     * @param alarmName alarmName
     * @param csn       incident流水号
     * @return 响应结果
     * @throws ServiceException 异常时抛出
     */
    public List<IncidentCase> queryAILlmEngineIncidentCases(HttpContext context, String alarmId, String alarmName, Long csn)
            throws ServiceException {
        LOGGER.info("[queryAILlmEngineIncidentCases] csn={}, alarmId={}, alarmName={}", csn, alarmId, alarmName);
        Incident incident = new Incident();
        incident.setCsn(csn);
        // 检索告警知识
        QueryParam incidentKnowledgeQuery = new QueryParam();
        incidentKnowledgeQuery.setIndexName(IndexManagerConstants.KNOWLEDGE_INDEX);
        incidentKnowledgeQuery.setQuery("ALM-" + alarmId + " " + alarmName);
        KnowledgeRecommendsRsp knowledgeRecommendsRsp = KnowledgeQuery.getEntityKnowledgeRecommendsRsp(context, incidentKnowledgeQuery);
        KnowledgeRsp alarmMatchedKnowledge = null;
        for (KnowledgeRsp knowledge : knowledgeRecommendsRsp.getRecommends()) {
            // 过滤告警知识
            if (Objects.equals(alarmId, extractAlarmId(knowledge.getTitle()))) {
                alarmMatchedKnowledge = knowledge;
            }
        }
        if (alarmMatchedKnowledge != null) {
            knowledgeRecommendsRsp.setRecommends(List.of(alarmMatchedKnowledge));
        } else {
            knowledgeRecommendsRsp.setRecommends(new ArrayList<>());
        }
        return incidentCaseManager.buildIncidentCases(knowledgeRecommendsRsp, incident);
    }

    /**
     * 智能事件案例检索
     *
     * @param context context
     * @param query   检索query
     * @param csn     incident流水号
     * @return 响应结果
     * @throws ServiceException 异常时抛出
     */
    public List<IncidentCase> queryAIIncidentCases(HttpContext context, String query, Long csn)
            throws ServiceException {
        Incident incident = new Incident();
        incident.setCsn(csn);
        // 检索预置知识
        QueryParam incidentKnowledgeQuery = new QueryParam();
        incidentKnowledgeQuery.setQuery(query);
        KnowledgeRecommendsRsp knowledgeRecommendsRsp = getKnowledgeRecommendsRsp(context, incidentKnowledgeQuery);
        List<IncidentCase> knowledgeList = incidentCaseManager.buildIncidentCases(knowledgeRecommendsRsp, incident);
        // 检索归档知识
        QueryParam incidentCaseArchiveQuery = new QueryParam();
        incidentCaseArchiveQuery.setQuery(query);
        incidentCaseArchiveQuery.setIndexName(ARCHIVED_KNOWLEDGE_INDEX);
        List<IncidentCase> archivedKnowledgeList = new ArrayList<>();
        try {
            KnowledgeRecommendsRsp archivedKnowledgeRecommendsRsp = getKnowledgeRecommendsRsp(context, incidentCaseArchiveQuery);
            archivedKnowledgeList.addAll(incidentCaseManager.buildIncidentCases(archivedKnowledgeRecommendsRsp, incident));
        } catch (ServiceException e) {
            LOGGER.error("[queryAIIncidentCases] ServiceException while getting archived incident cases for csn {}: {}",
                    incident.getCsn(), e.getMessage(), e);
        } catch (Exception e) {
            LOGGER.error("[queryAIIncidentCases] Unexpected error while getting archived incident cases for csn {}: {}",
                    incident.getCsn(), e.getMessage(), e);
        }
        if (CollectionUtils.isNotEmpty(archivedKnowledgeList)) {
            if (CollectionUtils.isNotEmpty(knowledgeList)) {
                knowledgeList.set(knowledgeList.size() - 1, archivedKnowledgeList.getFirst());
            } else {
                knowledgeList = List.of(archivedKnowledgeList.getFirst());
            }
        }
        return knowledgeList;
    }

