    @Override
    public ResponseResult topNIncident(HttpContext context, String solutionName, Integer num, Integer[] status)
            throws ServiceException {
        try {
            LOGGER.info("topNIncident start, solutionName: {}, num: {}, status: {}",
                    solutionName, num, status != null ? Arrays.toString(status) : "null");

            // Query local incidents from DVAIAgentService database
            // Query more than needed to ensure we have enough after merging
            int queryLimit = num * 2;
            List<Incident> localIncidents = queryTopNLocalIncident(status, queryLimit);
            LOGGER.info("Local incidents count: {}", localIncidents != null ? localIncidents.size() : 0);

            // Query AI incidents from DVAnalysisEngineService
            List<Incident> aiIncidents = new ArrayList<>();
            try {
                aiIncidents = incidentManage.getTopNAIIncidents(context, solutionName, queryLimit, status);
                LOGGER.info("AI incidents count: {}", aiIncidents != null ? aiIncidents.size() : 0);
            } catch (Exception e) {
                LOGGER.error("Failed to get AI incidents, continue with local incidents only", e);
            }

            // Merge all incidents
            List<Incident> allIncidents = new ArrayList<>();
            if (localIncidents != null) {
                allIncidents.addAll(localIncidents);
            }
            if (aiIncidents != null) {
                allIncidents.addAll(aiIncidents);
            }

            // Sort by priority (CRITICAL first, then HIGH, MEDIUM, LOW) then by startTime DESC
            allIncidents.sort((i1, i2) -> {
                // Compare priority - CRITICAL > HIGH > MEDIUM > LOW
                int priorityCompare = comparePriority(i1.getPriority(), i2.getPriority());
                if (priorityCompare != 0) {
                    return priorityCompare;
                }
                // Compare startTime - more recent first (DESC)
                long time1 = i1.getOccurTime();
                long time2 = i2.getOccurTime();
                return Long.compare(time2, time1);
            });

            // Return top N
            List<Incident> topN = allIncidents.stream()
                    .limit(num)
                    .collect(Collectors.toList());

            LOGGER.info("topNIncident success, returning {} incidents", topN.size());
            return ResponseResultHelper.correctResponseEntity(topN);

        } catch (Exception e) {
            LOGGER.error("topNIncident error", e);
            return ResponseResultHelper.failResponseEntity("Error: " + e.getMessage());
        }
    }

    /**
     * 获取当前环境上的TopN单告警事件
     *
     * @param status 状态
     * @param queryLimit Top数量
     * @return TopN单告警事件
     * @throws ServiceException 异常时抛出
     */
    private List<Incident> queryTopNLocalIncident(Integer[] status, int queryLimit) throws ServiceException {
        List<Incident> localIncidents = new ArrayList<>();
        List<String> queryDns = new ArrayList<>();
        // 基于授权网元进行过滤
        if (!ContextUtils.getContext().getAdmin()) {
            queryDns = incidentManage.getIncidentQueryDns();
            if (queryDns.isEmpty()) {
                return localIncidents;
            }
        }
        localIncidents = incidentDao.getTopNIncidents(status != null ? Arrays.stream(status)
            .map(IncidentStatus::of)
            .map(IncidentStatus::name)
            .toArray(String[]::new) : null, queryLimit, queryDns);
        return localIncidents;
    }

    private int comparePriority(com.huawei.cloudsop.aifm.databind.IncidentPriority priority1,
                                com.huawei.cloudsop.aifm.databind.IncidentPriority priority2) {
        int p1 = getPriorityValue(priority1);
        int p2 = getPriorityValue(priority2);
        return Integer.compare(p1, p2);
    }

    private int getPriorityValue(com.huawei.cloudsop.aifm.databind.IncidentPriority priority) {
        if (priority == null) {
            return 5; // Unknown priority goes last
        }
        switch (priority) {
            case CRITICAL:
                return 1;
            case HIGH:
                return 2;
            case MEDIUM:
                return 3;
            case LOW:
                return 4;
            default:
                return 5;
        }
    }

    /**
     * 驾舱事件统一入口
     *
     * @param context context
     * @param param   事件入参
     * @return 响应结果
     * @throws ServiceException 异常时抛出
     */
    @Override
    public ResponseResult addDiagnose(HttpContext context, AddDiagnoseParam param)
            throws ServiceException {
        String incidentType = param.getIncidentType();
        if (StringUtils.isEmpty(incidentType)) {
            LOGGER.error("[addDiagnose] Incident type is empty");
            return ResponseResultHelper.failResponseEntity("Incident type is empty.");
        }
        if (incidentType.equals(AI_INCIDENT) && param.getSmartIncident() != null) {
            LOGGER.info("[addDiagnose] start process ai incident");
            return faultDiagnose(context, param.getSmartIncident());
        } else if (incidentType.equals(ALARM) && param.getAlarmIncident() != null) {
            LOGGER.info("[addDiagnose] start process alarm incident");
            return addEvents(context, param.getAlarmIncident());
        } else {
            LOGGER.error("[addDiagnose] Param data not satisfied");
            return ResponseResultHelper.failResponseEntity("Param data not satisfied.");
        }
    }

    /**
     * 更新incident状态为自动完成
     *
     * @param incident 需要更新状态的incident
     * @return 如果更新成功返回true，否则返回false
     */
    public Boolean updateIncidentStatus(Incident incident) {
        incident.setTakeoverStatus(TAKEOVER_STATUS);
        List<Incident> incidents = new ArrayList<>();
        try {
            incidents.add(incident);
            incidentDao.addIncident(incidents);
            return true;
        } catch (ServiceException e) {
            LOGGER.error("Update incident status failed, message is {}.", e.getMessage());
            return false;
        }
    }

    /**
     * 检查是否可以接管incident。
     *
     * @param incident 需要检查的incident
     * @return 检查结果
     */
    public Boolean checkBeforeTakeOver(Incident incident) {
        return incident.getTakeoverStatus() == 0;
    }

    @Override
    public ResponseResult addEvents(HttpContext context, EventDtoList incidentDtoList)
            throws ServiceException {
        // Check origin alarm switch first
        boolean originAlarmSwitch = isOriginAlarmSwitch();
        if (!originAlarmSwitch) {
            return ResponseResultHelper.correctResponseEntity("ORIGINALARMSWITCH is false, no events processed");
        }
        // Convert DTO events to Event objects
        List<Event> events = JSON.parseArray(JSON.toJSONString(incidentDtoList.getEvents()), Event.class);
        String resultMessage = incidentManage.processAddEvent(context, events);

        return ResponseResultHelper.correctResponseEntity(resultMessage);
    }
