    private KnowledgeRecommendsRsp getKnowledgeRecommendsRsp(HttpContext context, QueryParam queryParam)
            throws ServiceException {
        RetrieverReq retrieverReq = getRetrieverReq(queryParam);
        String param = JSON.toJSONString(retrieverReq);
        RestfulParametes restfulParametes = new RestfulParametes();
        restfulParametes.setRawData(param);
        RestfulResponse knowledgeRsp = RestUtil.sendRestRequest(context.getHttpServletRequest(),
                RestConstant.RESTFUL_METHOD_POST, RETRIEVER_KLG_URL, restfulParametes, null);
        if (knowledgeRsp == null || knowledgeRsp.getStatus() != RestConstant.STATUS_OK) {
            LOGGER.error("[knowledgeSearch] query knowledge error");
            throw new ServiceException("[knowledgeSearch] query knowledge error");
        }

        return JSON.parseObject(knowledgeRsp.getResponseContent(), KnowledgeRecommendsRsp.class);
    }

    private RetrieverReq getRetrieverReq(QueryParam queryParam) {
        List<RetrieverIndex> ragIndexes = new ArrayList<>();
        ragIndexes.add(new RetrieverIndex(queryParam.getIndexName(), "KNOWLEDGE", ES_TOPN, VS_TOPN, new HashMap<>()));
        // cpu rag场景
        RankingOption rankingOption = new RankingOption("rrf", 0f);
        if (RAGConfig.isNpu()) {
            // npu rag场景
            rankingOption = new RankingOption("default", 0f);
        }
        RetrieverReq retrieverReq = new RetrieverReq(queryParam.getQuery(), RANK_TOPN, ragIndexes,
                false, rankingOption);

        return retrieverReq;
    }

    /**
     * 获取故障概览的方法
     *
     * @param context      Http请求上下文
     * @param status       状态
     * @param num          数量
     * @param unit         单位
     * @param displayTopo  是否展示拓扑
     * @param solutionName 是否展示拓扑
     * @return 返回故障概览的结果，包含事件列表
     */
    public ResponseResult overview(HttpContext context, Boolean displayTopo, String[] status, Integer num,
                                   String unit, String solutionName) {
        try {
            LOGGER.info("Overview param is displaytopo:{}, status:{}, num:{}, unit:{}",
                    displayTopo,
                    Arrays.asList(status),
                    num,
                    unit);
            IncidentQueryParam param = new IncidentQueryParam();
            IncidentDetailDto ret = new IncidentDetailDto();
            Long endTime = Instant.now().toEpochMilli();
            Long startTime = IncidentManage.getOccurTimeTimestamp(num, unit);
            ret.setEndTime(endTime);
            ret.setStartTime(startTime);
            int limit = NO_DISPLAY_TOPOLOGY_NUM;
            if (displayTopo) {
                limit = DISPLAY_TOPOLOGY_NUM;
            }
            EntityList<Incident> incidentList = incidentManage.incidentsForOverView(param, startTime, endTime, limit);
            if (incidentList.getTotal() == 0) {
                LOGGER.error("Alarm Incident Over view incidentList is null.");
            }

            List<Incident> incidents = getFinishedIncidents(incidentList, status);

            List<EventDetailDto> eventDetailDtoList = new ArrayList<>();

            for (Incident incident : incidents) {
                eventDetailDtoList.add(constructIncidentDto(incident, displayTopo));
            }

            ret.setEventDetailDtoList(eventDetailDtoList);
            try {
                AIIncidentOverViewDto overViewDto =
                        incidentManage.aiIncidentOverView(context, solutionName, startTime, endTime, displayTopo, status);
                ret.getEventDetailDtoList().addAll(convert(overViewDto.getAiIncidentDetailDtos()));
            } catch (Exception e) {
                LOGGER.error("get AI Incident overview exception", e);
            }

            processEventDetailDtoList(ret, displayTopo);
            LOGGER.info("IncidentDetailDto is {}", ret);
            filterEventDtos(ret, solutionName);
            return ResponseResultHelper.correctResponseEntity(ret);

        } catch (ServiceException e) {
            return ResponseResultHelper.failResponseEntity("ServiceException: {}" + e.getMessage());
        } catch (Exception e) {
            return ResponseResultHelper.failResponseEntity("Exception:{}" + e.getMessage());
        }
    }

