    public void filterEventDtos(IncidentDetailDto incidentDetailDto, String solutionName) {
        if (incidentDetailDto == null || incidentDetailDto.getEventDetailDtoList() == null) {
            return;
        }

        Integer solutionCode = SOLUTION_MAP.getOrDefault(solutionName.toUpperCase(Locale.ROOT), 1);

        for (EventDetailDto eventDetailDto : incidentDetailDto.getEventDetailDtoList()) {
            if (eventDetailDto == null || eventDetailDto.getEventDtos() == null) {
                continue;
            }

            eventDetailDto.getEventDtos().removeIf(eventTopoDto ->
                    eventTopoDto == null ||
                            eventTopoDto.getUpperLayerInfo() == null ||
                            !solutionCode.equals(eventTopoDto.getUpperLayerInfo().getSolutionType())
            );
        }
    }

    public void processEventDetailDtoList(IncidentDetailDto ret, Boolean displayTopo) {
        List<EventDetailDto> eventDetailDtoList = ret.getEventDetailDtoList();
        if (eventDetailDtoList == null || eventDetailDtoList.isEmpty()) {
            return;
        }

        eventDetailDtoList.sort((dto1, dto2) -> {
            Long time1 = dto1.getOccurTime();
            Long time2 = dto2.getOccurTime();

            if (time1 == null && time2 == null) {
                return 0;
            }
            if (time1 == null) {
                return 1;
            }
            if (time2 == null) {
                return -1;
            }

            return time2.compareTo(time1);
        });

        int limit = displayTopo ? DISPLAY_TOPOLOGY_NUM : NO_DISPLAY_TOPOLOGY_NUM;
        if (eventDetailDtoList.size() > limit) {
            ret.setEventDetailDtoList(eventDetailDtoList.subList(0, limit));
        }
    }

    public List<EventDetailDto> convert(List<AIIncidentDetailDto> aiIncidentDetailDtos) {
        return aiIncidentDetailDtos.stream()
                .map(this::convert)
                .collect(Collectors.toList());
    }

    public EventDetailDto convert(AIIncidentDetailDto dto) {
        EventDetailDto eventDetailDto = new EventDetailDto();
        eventDetailDto.setCategory(AI_INCIDENT);
        eventDetailDto.setCsn(dto.getCsn());
        eventDetailDto.setDiagnosticStatusEnum(DiagnosticStatusEnum.fromIncidentConstantCode(dto.getDiagnosticStatusEnum()));
        eventDetailDto.setOccurTime(dto.getOccurTime());
        eventDetailDto.setIncidentName(dto.getIncidentName());
        eventDetailDto.setDescription(dto.getDescription());

        List<EventTopoDto> eventDtos = convertToEventTopoDtos(dto.getMoList(), dto.getKeyEventList());
        eventDetailDto.setEventDtos(eventDtos);

        return eventDetailDto;
    }

    public List<EventTopoDto> convertToEventTopoDtos(IncidentDetailMoList moList, List<KeyEvent> keyEventList) {
        Set<String> uniqueDns = extractUniqueDns(keyEventList);

        Map<String, TopoMo> appDnMap = moList.getApp().stream()
                .collect(Collectors.toMap(TopoMo::getDn, mo -> mo, (existing, replacement) -> existing));

        List<EventTopoDto> eventTopoDtos = new ArrayList<>();
        for (String dn : uniqueDns) {
            EventTopoDto eventTopoDto = new EventTopoDto();
            eventTopoDto.setNativeMoDn(dn);

            UpperLayerInfo upperLayerInfo = new UpperLayerInfo();
            TopoMo matchedMo = appDnMap.get(dn);
            if (matchedMo != null) {
                upperLayerInfo.setGroupId(matchedMo.getGroupId());
            }
            eventTopoDto.setUpperLayerInfo(upperLayerInfo);
            eventTopoDtos.add(eventTopoDto);
        }

        return eventTopoDtos;
    }

    public Set<String> extractUniqueDns(List<KeyEvent> keyEventList) {
        Set<String> dns = new HashSet<>();
        if (keyEventList == null) {
            return dns;
        }

        for (KeyEvent event : keyEventList) {
            String dnListStr = event.getDnList();
            if (dnListStr != null && !dnListStr.trim().isEmpty()) {
                try {
                    List<String> dnList = JSON.parseArray(dnListStr, String.class);
                    dns.addAll(dnList);
                } catch (JSONException e) {
                    LOGGER.error("extractUniqueDns exception, list is {}", keyEventList, e);
                }
            }
        }

        return dns;
    }

    /**
     * 构造一个IncidentDto对象，该对象包含了Incident的名称和事件信息。
     *
     * @param incident    需要转换的Incident对象
     * @param displayTopo 是否展示拓扑
     * @return 返回一个包含Incident信息的EventDetailDto对象
     * @throws ServiceException 当服务异常时抛出
     */
    public EventDetailDto constructIncidentDto(Incident incident, Boolean displayTopo)
            throws ServiceException {
        EventDetailDto eventDetailDto = new EventDetailDto();
        eventDetailDto.setIncidentName(incident.getName());
        eventDetailDto.setDescription(incident.getDescription());
        eventDetailDto.setCsn(incident.getCsn());
        eventDetailDto.setOccurTime(incident.getOccurTime());
        eventDetailDto.setDiagnosticStatusEnum(incident.getDiagnosticStatus());

        if (!displayTopo) {
            return eventDetailDto;
        }

        List<EventTopoDto> eventTopoDtos = new ArrayList<>();
        if (checkIncidentType(incident)) {
            EventTopoDto eventTopoDto = new EventTopoDto();
            eventTopoDto.setNativeMoDn(incident.getSourceObjId());
            eventTopoDto.setOccurTime(incident.getOccurTime());
            eventTopoDtos.add(eventTopoDto);
        } else {
            eventTopoDtos = getEventsFromIncident(incident.getCsn());
        }

        DnListDto dnListDto = constructDnListDto(eventTopoDtos);

        eventTopoDtos = completeTopologyData(eventTopoDtos, dnListDto);

        eventDetailDto.setEventDtos(eventTopoDtos);
        return eventDetailDto;
    }

    private boolean checkIncidentType(Incident incident) {
        if (!"KPI".equals(incident.getCategory())) {
            return false;
        }

        return !StringUtils.isEmpty(incident.getSourceObjId());
    }

    /**
     * 完善拓扑数据
     *
     * @param eventTopoDtos 事件拓扑数据列表
     * @param dnListDto     需要查询的DN列表
     * @return 事件拓扑数据列表
     */
    public List<EventTopoDto> completeTopologyData(List<EventTopoDto> eventTopoDtos, DnListDto dnListDto) {
        try {
            ResponseResult result = cockpitServiceDelegate.getTopoNeTypeByDn(null, dnListDto);

            if (result.getResultCode() != 0) {
                LOGGER.error("cockpitServiceDelegate getTopoNeTypeByDn fail.");
                return eventTopoDtos;
            }

            List<UpperLayerInfo> upperLayerInfos = safeCastToUpperLayerInfoList(result.getData());

            Map<String, UpperLayerInfo> upperLayerInfoMap = upperLayerInfos.stream()
                    .collect(Collectors.toMap(
                            info -> info.getDn() + "_" + info.getTimestamp(),
                            info -> info,
                            (existing, replacement) -> existing
                    ));

            eventTopoDtos.forEach(eventTopoDto -> {
                String key = eventTopoDto.getNativeMoDn() + "_" + eventTopoDto.getOccurTime();
                UpperLayerInfo upperLayerInfo = upperLayerInfoMap.get(key);
                if (upperLayerInfo != null) {
                    eventTopoDto.setUpperLayerInfo(upperLayerInfo);
                }
            });

            return eventTopoDtos;

        } catch (ServiceException e) {
            LOGGER.error("Get topodto occur exception {}", e.getMessage());
            return eventTopoDtos;
        }
    }

    /**
     * 安全地转换UpperLayerInfo 检查不通过将抛出IllegalStateException。
     *
     * @param data 需要转换的数据
     * @return 转换后的UpperLayerInfo类型的列表
     * @throws IllegalStateException 检查失败
     */
    public List<UpperLayerInfo> safeCastToUpperLayerInfoList(Object data) {
        List<UpperLayerInfo> infos = new ArrayList<>();

        if (data == null) {
            return infos;
        }
        if (!(data instanceof List<?>)) {
            LOGGER.error("The obtained data is not of the list type.");
            return infos;
        }

        List<?> dataList = (List<?>) data;

        for (Object item : dataList) {
            if (!(item instanceof UpperLayerInfo)) {
                LOGGER.error("The list contains elements of non-UpperLayerInfo type: {}", item);
                continue;
            }
            infos.add((UpperLayerInfo) item);
        }

        return infos;
    }

    /**
     * 构建DnListDto对象
     *
     * @param events EventTopoDto对象列表
     * @return 返回DnListDto对象
     */
    public static DnListDto constructDnListDto(List<EventTopoDto> events) {
        DnListDto dnListDto = new DnListDto();
        List<DnDto> paramList = events.stream()
                .filter(Objects::nonNull)
                .map(eventTopoDto -> {
                    DnDto dnDto = new DnDto();
                    dnDto.setDn(eventTopoDto.getNativeMoDn());
                    dnDto.setTimestamp(eventTopoDto.getOccurTime());
                    return dnDto;
                })
                .collect(Collectors.toList());
        dnListDto.setParamList(paramList);
        return dnListDto;
    }

